"""Explain result tests and conditional arithmetic at zero boundaries."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1557': ('온도계가 -1도에서 1도 올라 0도가 되었어요. “온도가 0인가요?”의 답은 “네”예요. 숫자 0과 “네”라는 대답은 서로 다른 종류의 결과예요.', '계산 뒤 숫자와 그 숫자에 대한 참·거짓 대답을 구별합니다.', '-1+1=0 옆에 inc_and_test 반환 true를 적으세요. 0+1=1 옆에는 반환 false를 적고, 두 경우 모두 덧셈은 했다고 표시하세요.', ['bool은 true 또는 false를 담는 자료형이에요. true는 물어본 조건이 맞다는 “네”, false는 맞지 않는다는 “아니요”예요. 무엇을 물어보는 함수인지 먼저 알아야 대답을 해석할 수 있어요.', 'inc_and_test는 1을 더한 뒤 결과가 0인지 물어요. -1에서 시작하면 0을 저장하고 true를 반환해요. 0에서 시작하면 1을 저장하고 false를 반환해요. false인 두 번째 경우도 덧셈은 실행했어요.', 'dec_and_test는 1을 뺀 뒤 0인지 물어요. 1에서 시작하면 저장 0·반환 true, 2에서 시작하면 저장 1·반환 false예요. sub_and_test는 지정한 수를 뺀 뒤 0인지 묻는 형태예요.', 'add_negative는 더한 뒤 값이 음수인지 물어요. 음수는 -1이나 -2처럼 0보다 작은 수예요. -3에 1을 더하면 -2라서 true, -1에 1을 더하면 0이라서 false예요. 0은 음수가 아니에요.', 'return 계열은 계산한 숫자 자체를 알려 주지만 이 test 계열은 조건의 대답을 알려 줘요. “계산이 성공했나요?”와 “계산 결과가 0인가요?”를 섞지 마세요. 대상 숫자 갱신과 그 결과 검사는 한 원자 연산의 결과를 기준으로 해요.', '이 헤더의 기본 결과 검사 함수들은 full ordering이라는 메모리 접근 순서 약속을 제공해요. add_negative에는 acquire·release·relaxed 형태도 있어요. 다만 0을 확인했다는 사실만으로 자료를 안전하게 지워도 된다는 뜻은 아니에요. 다른 사람이 아직 자료를 쓰는지 판단하는 규칙은 따로 필요해요.'], [('초깃값 -1에서 inc_and_test로 1을 더했어요. 저장값과 반환값은 무엇인가요?', ['0을 저장하고 false를 반환해요', '0을 저장하고 true를 반환해요'], '정답은 두 번째예요. -1+1=0이고 이 함수는 결과가 0인지 물어요. 조건에 맞으므로 true예요. 저장된 0을 그대로 참·거짓 대답으로 읽으면 안 돼요.'), ('add_negative가 알려 주는 true·false는 어떤 질문의 대답인가요?', ['더한 뒤 결과가 0보다 작은가요?', '더하기 전 값이 반드시 0인가요?'], '정답은 첫 번째예요. negative는 음수라는 뜻이고 검사 대상은 계산 뒤 값이에요. -3+1=-2는 true, -1+1=0은 false예요.')]), 'os1558': ('“숫자판이 0이면 쉬고, 0이 아니면 2를 더해 주세요”라는 규칙이에요. 일을 한 뒤 이전 숫자를 알려 주는 방법도 있고, 계산을 했는지만 알려 주는 방법도 있어요.', 'unless의 금지 값 조건과 두 반환 방식의 차이를 이해합니다.', '시작 5·더할 값 2·금지 값 0의 표를 두 개 만드세요. 둘 다 저장 7, add_unless 반환 true, fetch_add_unless 반환 5라고 적으세요.', ['unless는 “그 경우가 아니라면”이라는 뜻이에요. add_unless(v, a, u)는 v의 값이 u와 다르면 a를 더해요. u와 같으면 더하지 않고 그대로 둬요. u는 시작 값을 검사하는 기준이지 결과값의 상한선이 아니에요.', '현재 값 5, 더할 수 a=2, 금지 값 u=0이면 5와 0이 다르므로 7을 저장해요. add_unless는 이때 true를 반환해요. true는 조건에 따라 갱신을 수행했다는 대답이에요. 이전 숫자 5를 반환하는 함수가 아니에요.', 'fetch_add_unless도 같은 조건으로 계산하지만 이전 값을 반환해요. 별도 숫자판을 5로 시작하면 저장 7·반환 5예요. fetch가 붙었는지에 따라 반환값의 종류가 달라지므로 이름을 끝까지 읽어야 해요.', '현재 값과 금지 값이 둘 다 0이면 두 함수 모두 숫자판을 그대로 둬요. add_unless는 false를, fetch_add_unless는 이전 값 0을 반환해요. fetch 형태는 반환값을 금지 값 u와 비교해 갱신 여부를 판단해요.', '조건에 맞아 갱신하면 full ordering이라는 순서 약속을 제공하지만, 조건이 맞지 않아 건너뛰면 relaxed예요. 반환값이 있다는 이유만으로 실패 때에도 다른 자료에 대한 강한 순서 보장이 생기지는 않아요.', '이 함수가 값을 최대치에 붙잡아 두거나 자료를 지울 권한까지 정해 주지는 않아요. 그런 최대치 유지 동작을 포화라고 해요. 자료를 사용하는 사람 수를 관리한다면 전용 refcount_t의 규칙과 자료가 살아 있는 동안만 접근하는 방법도 살펴봐야 해요. 여기서는 먼저 숫자 조건과 반환 방식에 집중하세요.'], [('숫자판 5, 더할 값 2, 금지 값 0으로 add_unless를 실행했어요. 무엇을 반환하나요?', ['이전 숫자 5를 반환해요', '갱신을 수행했다는 true를 반환해요'], '정답은 두 번째예요. 5는 0이 아니므로 7을 저장하고 true를 알려 줘요. 이전 숫자 5를 반환하는 것은 fetch_add_unless예요.'), ('현재 값이 금지 값과 같아서 계산을 건너뛰었어요. 실패 때에도 full ordering을 보장하나요?', ['아니요. 이 실패 경로의 순서 약속은 relaxed예요', '네. 반환값이 있으니 실패도 무조건 full ordering이에요'], '정답은 첫 번째예요. 조건부 연산은 성공과 실패의 순서 약속을 나눠 읽어야 해요. 숫자를 반환하는지와 다른 자료의 접근 순서를 보장하는지는 같은 질문이 아니에요.')]), 'os1559': ('수직선에서 -1은 0 왼쪽, 1은 0 오른쪽이에요. 0은 음수도 양수도 아니므로 “음수만 빼고”와 “0만 빼고”는 다른 규칙이에요.', '음수·0·양수에 따라 허용되는 증가와 감소를 구별합니다.', '-1·0·1 세 칸에 inc_not_zero 결과 0·0·2, inc_unless_negative 결과 -1·1·2, dec_unless_positive 결과 -2·-1·1을 적고 바뀌지 않은 칸에 동그라미를 치세요.', ['음수는 0보다 작은 수, 양수는 0보다 큰 수예요. 0은 둘 다 아니에요. 부등식 >=0은 “0 또는 양수”, <=0은 “음수 또는 0”이라는 뜻이에요.', 'inc_not_zero는 “0이 아니면 1을 더하기”예요. -1에서는 0으로 바꾸고 true, 0에서는 그대로 두고 false, 1에서는 2로 바꾸고 true예요. 이름의 not_zero는 음수를 금지한다는 뜻이 아니에요.', 'inc_unless_negative는 “음수만 빼고 1을 더하기”예요. 조건을 식으로 쓰면 현재 값 >=0이에요. -1은 건너뛰고 0은 1로, 1은 2로 바꿔요. 0도 허용된다는 점이 앞 함수와 달라요.', 'dec_unless_positive는 “양수만 빼고 1을 빼기”예요. 현재 값 <=0일 때 계산해요. -1은 -2로, 0은 -1로 바꾸고 1은 그대로 둬요. 양수일 때만 감소시키는 dec_if_positive와 이름을 혼동하지 마세요.', '셋 모두 갱신을 수행하면 true, 조건 때문에 건너뛰면 false를 반환해요. 성공 때 순서 약속은 full ordering이고 실패 때는 relaxed예요. 반환 true는 결과가 양수라는 뜻이 아니에요. 0에서 -1로 바뀌어도 세 번째 함수는 true예요.', '이 조건들은 부호나 0 여부를 검사할 뿐, 모든 범위 초과를 막는 안전장치는 아니에요. 컴퓨터 정수는 담을 수 있는 범위가 정해져 있어요. 큰 끝값의 계산은 별도로 따져야 하므로 이 연습에서는 -1·0·1처럼 작은 수로 조건을 먼저 익혀요.'], [('0에서 inc_unless_negative를 실행하면 1을 더하나요?', ['아니요. 0도 음수라서 건너뛰어요', '네. 0은 음수가 아니라 1로 바꿔요'], '정답은 두 번째예요. 음수는 0보다 작은 수예요. 조건 >=0에는 0이 포함되므로 1을 더하고 true를 반환해요.'), ('0에서 dec_unless_positive를 실행하면 어떻게 되나요?', ['0은 양수가 아니라 -1로 바꾸고 true를 반환해요', '양수일 때만 빼므로 0을 그대로 둬요'], '정답은 첫 번째예요. unless_positive는 양수인 경우를 제외한다는 뜻이에요. 조건 <=0에 0이 들어가므로 1을 빼요. 두 번째 답은 dec_if_positive와 혼동한 것이에요.')]), 'os1560': ('사탕 통이 비어 있으면 사탕을 꺼낼 수 없어요. 하지만 “지금 개수에서 1을 빼면 얼마일까?”라는 계산은 할 수 있어요. 실제 통의 개수와 계산한 숫자를 나눠 봅시다.', '조건부 감소의 실제 저장값과 계산해서 반환하는 값을 구별합니다.', '시작 0·1·2의 표를 만드세요. 저장값은 0·0·1, 반환값은 -1·0·1로 적으세요. 시작 0일 때 두 줄이 다른 이유를 말해 보세요.', ['dec_if_positive는 “양수라면 1을 줄이기”라는 이름이에요. 이 수업에서는 개수를 나타내는 정상 입력 0·1·2처럼 음수가 아닌 작은 수로 동작을 따라가요. 양수는 0보다 큰 수예요.', '시작 값이 2이면 1을 빼서 1을 저장하고 1을 반환해요. 시작 값이 1이면 0을 저장하고 0을 반환해요. 반환은 true·false가 아니라 계산한 숫자예요. 따라서 반환 0도 정상적으로 감소한 결과일 수 있어요.', '시작 값이 0이면 실제 숫자판은 0 그대로 둬요. 하지만 반환값은 이전 값에서 1을 뺀 -1이에요. 반환 -1을 숫자판에 저장했다고 읽으면 안 돼요. 저장하지 않아도 계산한 결과는 알려 줄 수 있어요.', '정상적인 음수 아닌 입력 범위에서는 반환이 0 이상이면 감소한 경우이고, 0에서 시도해 반환이 -1이면 감소하지 않은 경우예요. “0 반환은 언제나 실패”나 “음수 반환을 그대로 저장했다”는 해석은 둘 다 틀려요.', '헤더는 성공 때 full ordering, 조건에 맞지 않는 실패 때 relaxed라는 메모리 접근 순서 규칙도 적고 있어요. 위에서 본 dec_unless_positive는 0에서 -1을 저장하는 다른 함수예요. if_positive와 unless_positive의 조건을 바꿔 읽지 마세요.', '이 설명을 모든 극단적인 정수 입력으로 넓히지는 마세요. 가장 작은 음수에서 1을 빼는 경우는 실제로 연결되는 구현과 정수 범위 초과 규칙까지 확인해야 해요. 이 함수는 사용 개수를 최대치에 고정하거나 자료의 수명을 자동 보호하는 전용 도구가 아니에요. 여기서 다룬 0·1·2의 저장과 반환을 먼저 정확히 구별하세요.'], [('초깃값 0에서 dec_if_positive를 실행했어요. 반환값과 저장값은 무엇인가요?', ['실패 표시 0을 반환하고 -1을 저장해요', '계산값 -1을 반환하고 저장값은 0으로 유지해요'], '정답은 두 번째예요. 0은 양수가 아니라 실제 감소는 하지 않아요. 그래도 이전 값에서 1을 뺀 계산 결과 0-1=-1을 반환해요. 반환과 저장은 별개예요.'), ('초깃값 2에서 dec_if_positive를 실행하면 무엇을 반환하나요?', ['2-1의 결과인 1을 반환해요', '성공하면 언제나 0을 반환해요'], '정답은 첫 번째예요. 2는 양수라서 1을 저장하고 계산 결과 1을 반환해요. 이 함수는 성공 표시를 항상 0으로 만드는 함수가 아니에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_385.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
